import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right columns with correct types
    if target_state.empty:
        target_state = pd.DataFrame({
            'order_id': pd.Series([], dtype='int64'),
            'status': pd.Series([], dtype='object'),
            'amount': pd.Series([], dtype='float64'),
            'last_seq': pd.Series([], dtype='int64')
        })

    # Ensure cdc_events has the right columns with correct types
    if cdc_events.empty:
        cdc_events = pd.DataFrame({
            'seq': pd.Series([], dtype='int64'),
            'order_id': pd.Series([], dtype='int64'),
            'op': pd.Series([], dtype='object'),
            'status': pd.Series([], dtype='object'),
            'amount': pd.Series([], dtype='float64'),
            'event_ts': pd.Series([], dtype='datetime64[us]')
        })

    # Step 1: Remove duplicate events (keep first occurrence of each seq)
    cdc_events = cdc_events.drop_duplicates(subset=['seq'], keep='first')

    # Step 2: Sort by seq to process in order
    cdc_events = cdc_events.sort_values('seq').reset_index(drop=True)

    # Step 3: Create a working copy of target_state indexed by order_id
    state_dict = {}
    for _, row in target_state.iterrows():
        order_id = row['order_id']
        state_dict[order_id] = {
            'status': row['status'],
            'amount': row['amount'],
            'last_seq': row['last_seq']
        }

    # Track which orders have been touched and their final operation
    order_last_op = {}  # order_id -> (op, seq)

    # Step 4: Process each event in seq order
    for _, event in cdc_events.iterrows():
        seq = event['seq']
        order_id = event['order_id']
        op = event['op']
        status = event['status']
        amount = event['amount']

        # Replay guard: skip if this order exists in target_state and seq <= last_seq
        if order_id in state_dict and seq <= state_dict[order_id]['last_seq']:
            continue

        # Apply the event
        if op in ['I', 'U']:
            if order_id not in state_dict:
                # Create new row
                state_dict[order_id] = {
                    'status': status,
                    'amount': amount,
                    'last_seq': seq
                }
            else:
                # Update existing row
                state_dict[order_id]['status'] = status
                # For 'U', NULL amount means keep the old amount; for 'I', always overwrite
                if op == 'I' or not pd.isna(amount):
                    state_dict[order_id]['amount'] = amount
                state_dict[order_id]['last_seq'] = seq

            order_last_op[order_id] = (op, seq)

        elif op == 'D':
            # Delete the row if it exists
            if order_id in state_dict:
                del state_dict[order_id]
            order_last_op[order_id] = (op, seq)

    # Step 5: Build new_state from state_dict
    new_state_rows = []
    for order_id, state in state_dict.items():
        new_state_rows.append({
            'order_id': order_id,
            'status': state['status'],
            'amount': state['amount'],
            'last_seq': state['last_seq']
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.sort_values('order_id').reset_index(drop=True)
    else:
        new_state = pd.DataFrame({
            'order_id': pd.Series([], dtype='int64'),
            'status': pd.Series([], dtype='object'),
            'amount': pd.Series([], dtype='float64'),
            'last_seq': pd.Series([], dtype='int64')
        })

    # Step 6: Build tombstones for orders whose last applied event was 'D'
    tombstone_rows = []
    for order_id, (op, seq) in order_last_op.items():
        if op == 'D':
            tombstone_rows.append({
                'order_id': order_id,
                'deleted_seq': seq
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.sort_values('order_id').reset_index(drop=True)
    else:
        tombstones = pd.DataFrame({
            'order_id': pd.Series([], dtype='int64'),
            'deleted_seq': pd.Series([], dtype='int64')
        })

    return {
        'new_state': new_state,
        'tombstones': tombstones
    }
